#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    long long mid = (long long)n * (n - 1) / 2;
    long long max_idx = (long long)n * (n - 1);
    vector<vector<long long>> dp_array(n + 1, vector<long long>(max_idx + 1, 0));
    vector<vector<long long>> dp1_array(n + 1, vector<long long>(max_idx + 1, 0));
    dp_array[1][mid] = 1;
    for (int i = 2; i <= n; ++i) {
        long long low = mid - (long long)(i - 1) * (i - 2) / 2;
        long long high = mid + (long long)(i - 1) * (i - 2) / 2;
        for (long long x = low; x <= high; ++x) {
            for (int delta = -i + 1; delta < i; ++delta) {
                long long idx = x + delta;
                if (0 <= idx && idx <= max_idx) {
                    long long val = (dp_array[i][idx] + dp_array[i - 1][x] * (i - abs(delta))) % mod;
                    dp_array[i][idx] = val;
                }
            }
        }
    }
    for (int i = 2; i <= n; ++i) {
        long long low = mid - (long long)(i - 1) * (i - 2) / 2;
        long long high = mid + (long long)(i - 1) * (i - 2) / 2;
        for (long long x = low; x <= high; ++x) {
            long long val = (dp1_array[i - 1][x] * i) % mod;
            dp1_array[i][x] = val;
        }
        for (int i2 = 2; i2 <= n; ++i2) {
            long long low2 = mid - (long long)(i2 - 1) * (i2 - 2) / 2;
            long long high2 = mid + (long long)(i2 - 1) * (i2 - 2) / 2;
            for (long long x = low2; x <= high2; ++x) {
                for (int d = 1; d < i2; ++d) {
                    long long idx = x - d;
                    if (0 <= idx && idx <= max_idx) {
                        long long val = (dp1_array[i2][idx] + dp_array[i2 - 1][x] * (i2 - d)) % mod;
                        dp1_array[i2][idx] = val;
                    }
                }
            }
        }
    }
    long long result = 0;
    for (long long x = mid + 1; x <= max_idx; ++x) {
        result = (result + dp1_array[n][x]) % mod;
    }
    cout << result << "\n";
    return 0;
}

